schemaSql:
CREATE TABLE accounts (
  id INTEGER PRIMARY KEY,
  user_id INTEGER,
  account_type TEXT,
  opened_date TEXT
);
CREATE TABLE transactions (
  id INTEGER PRIMARY KEY,
  account_id INTEGER,
  txn_type TEXT,
  amount REAL,
  txn_date TEXT
);

